/**
 * @param {character[][]} grid
 * @return {boolean}
 */
var hasValidPath = function(grid) {
    const m = grid.length;
    const n = grid[0].length;
    const memo = new Map();

    const explore = (row, col, count) => {
        if (row < 0 || row >= m || col < 0 || col >= n) return false;

        const key = row + ':' + col + ':' + count;
        if (memo.has(key)) return memo.get(key);

        if (grid[row][col] === '(') {
            count++;
        } else {
            if (count === 0) {
                memo.set(key, false);
                return false;
            }
            count--;
        }

        if (row === m - 1 && col === n - 1 && count === 0) return true;

        const res = explore(row, col + 1, count) ||
            explore(row + 1, col, count);

        memo.set(key, res);
        return res;
    };

    return explore(0, 0, 0);
};

